Example 1:

Input: expression = "()[]{}"
Output: true

Example 2:

Input: expression = "(]"
Output: false

Example 3:

Input: expression = "([)]"
Output: false

Example 4:

Input: expression = "{[]}"
Output: true

Constraints:

1 <= expression.length <= 10^5
expression consists of only '(' and ')' and '{' and '}'

class Solution {
public:
    bool checkValidString(string s) {
        int low = 0, high = 0;
        for (char c : s) {
            if (c == '(') low++, high++;
            else if (c == ')') low--;
            else low--, high = max(high, low + 1);
            if (low < 0) return false;
        }
        return low == 0;
    }
};

