function move(str, num) {
  let result = '';
  let arr = str.split('');
  let arrNum = num.toString().split('');

  for (let i = 0; i < arr.length; i++) {
    if (isNaN(arr[i])) {
      result += arr[i];
    } else {
      result += arrNum[i];
    }
  }

  return result;
}

