def secondMostFrequent(arr):
    freq = {}
    max_count = 0
    second_max_count = 0
    for word in arr:
        if word in freq:
            freq[word] += 1
        else:
            freq[word] = 1
        if freq[word] > max_count:
            second_max_count = max_count
            max_count = freq[word]
        elif freq[word] > second_max_count and freq[word] != max_count:
            second_max_count = freq[word]
    for word, count in freq.items():
        if count == second_max_count:
            return word

# Driver code
