```
function minHeap(arr) {
  const heap = [...arr];

  function siftUp(index) {
    if (index === 0) return;

    const parentIndex = Math.floor((index - 1) / 2);
    if (heap[parentIndex] > heap[index]) {
      [heap[parentIndex], heap[index]] = [heap[index], heap[parentIndex]];
      siftUp(parentIndex);
    }
  }

  function siftDown(index) {
    const leftChildIndex = 2 * index + 1;
    const rightChildIndex = 2 * index + 2;

    let minIndex = index;

    if (
      leftChildIndex < heap.length &&
      heap[leftChildIndex] < heap[minIndex]
    ) {
      minIndex = leftChildIndex;
    }

    if (
      rightChildIndex < heap.length &&
      heap[rightChildIndex] < heap[minIndex]
    ) {
      minIndex = rightChildIndex;
    }

    if (minIndex !== index) {
      [heap[minIndex], heap[index]] = [heap[index], heap[minIndex]];
      siftDown(minIndex);
    }
  }

  for (let i = 0; i < heap.length; i++) {
    siftUp(i);
  }

  function pop() {
    if (heap.length === 0) return undefined;

    const min = heap[0];
    heap[0] = heap[heap.length - 1];
    heap.pop();
    siftDown(0);

    return min;
  }

  return {
    pop,
  };
}

const minHeap = minHeap([10, 5, 1, 12, 25, 55, 1]);
console.log(minHeap.pop()); // 1
console.log(minHeap.pop()); // 5
console.log(minHeap.pop()); // 10
```

